\mathrm{FunctorData}(F,\mathcal C,\mathcal D)\Longleftrightarrow
F_0\in(\operatorname{Ob}_{\mathcal D})^{\operatorname{Ob}_{\mathcal C}}
\land F_1\in(\operatorname{Mor}_{\mathcal D})^{\operatorname{Mor}_{\mathcal C}}.

\mathrm{FunctorGraph}(F,\mathcal C,\mathcal D)\Longleftrightarrow
\begin{cases}
\begin{gathered}
(\forall f\in\operatorname{Mor}_{\mathcal C})\
s_{\mathcal D}(F_1f)=F_0(s_{\mathcal C}f)\land
t_{\mathcal D}(F_1f)=F_0(t_{\mathcal C}f)
\end{gathered}&\mathrm{FunctorData}(F,\mathcal C,\mathcal D),\\
\bot&\neg\mathrm{FunctorData}(F,\mathcal C,\mathcal D).
\end{cases}

\mathrm{Functor}(F,\mathcal C,\mathcal D)\Longleftrightarrow
\begin{cases}
\begin{gathered}
(\forall A\in\operatorname{Ob}_{\mathcal C})\
F_1(\operatorname{id}_A)=\operatorname{id}_{F_0A}\\
\land(\forall(g,f)\in M^{(2)}_{\mathcal C})\
F_1(g\circ f)=F_1g\circ F_1f
\end{gathered}&\mathrm{FunctorGraph}(F,\mathcal C,\mathcal D),\\
\bot&\neg\mathrm{FunctorGraph}(F,\mathcal C,\mathcal D).
\end{cases}
